shapes.code:
use strict;
use warnings;

# Perl 5 objects: a hash reference 'blessed' into a package (class).
package Rectangle {
    sub new  { my ($class, %args) = @_; return bless {%args}, $class }
    sub area { my $self = shift; return $self->{width} * $self->{height} }
}

package Triangle {
    sub new  { my ($class, %args) = @_; return bless {%args}, $class }
    sub area { my $self = shift; return $self->{base} * $self->{height} / 2 }
}

package main;

for my $shape (Rectangle->new(width => 3, height => 4),
               Triangle->new(base => 10, height => 3)) {
    printf "%s: %d\n", ref $shape, $shape->area;
}

signature.code:
use strict;
use warnings;

# Perl's home turf: read lines, match regexes, rewrite text, tally in a hash.
my %count;
while (<DATA>) {
    next unless /^(\S+) \s+ (ERROR|WARN|INFO) \s+ (.*)/x;
    my ($date, $level, $msg) = ($1, $2, $3);
    $count{$level}++;
    next unless $level eq 'ERROR';
    $msg =~ s{/dev/(\w+)}{[$1]}g;    # rewrite device paths in place
    print "$date $msg\n";
}
print join(', ', map { "$_=$count{$_}" } sort keys %count), "\n";

